        slug: system,
        facility: facilityId,
        count,
        search: search + searchPostFix,
      },
    }),
    enabled: !pinnedValuesetId && !!system,
  });

  const searchQuery = pinnedValuesetId ? pinnedSearchQuery : slugSearchQuery;

