export default function ValueSetSearchContent({
  system,
  valuesetId: pinnedValuesetId,
  onSelect,
  count = 10,
  searchPostFix = "",
  showCode = false,
  search,
  onSearchChange,
  placeholder,
  title,
}: Props) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const [activeTab, setActiveTab] = useState(0);
  const [itemToRemove, setItemToRemove] = useState<CodeConceptMinimal | null>(
    null,
  );
  const [showBulkClearConfirm, setShowBulkClearConfirm] = useState(false);

  // Outside a facility route this is undefined, and the backend falls back to
  // instance-level valuesets.
  const { facilityId } = useCurrentFacilitySilently();

  const pinnedSearchQuery = useQuery({
    queryKey: ["valueset", pinnedValuesetId, "expand", count, search],
    queryFn: query.debounced(valueSetApi.expand, {
      pathParams: { id: pinnedValuesetId ?? "" },
      body: {
        count,
        search: search + searchPostFix,
      },
    }),
    enabled: !!pinnedValuesetId,
  });

  const slugSearchQuery = useQuery({
    queryKey: ["valueset", system, facilityId, "expand_slug", count, search],
    queryFn: query.debounced(valueSetApi.expandSlug, {
      body: {
        slug: system,
        facility: facilityId,
        count,
        search: search + searchPostFix,
      },
    }),
    enabled: !pinnedValuesetId && !!system,
  });

  const searchQuery = pinnedValuesetId ? pinnedSearchQuery : slugSearchQuery;

  // The slug -> valueset mapping does not vary with the search term, so it is
  // resolved on its own key. Deriving it from slugSearchQuery would drop it on
  // every keystroke, and the write endpoints are still id-keyed.
  const resolveQuery = useQuery({
    queryKey: ["valueset", "resolve", system, facilityId],
    queryFn: query(valueSetApi.expandSlug, {
      body: { slug: system, facility: facilityId, search: "", count: 1 },
      silent: true,
    }),
    enabled: !pinnedValuesetId && !!system,
    staleTime: Infinity,
  });

  const valuesetId = pinnedValuesetId ?? resolveQuery.data?.valueset.id;

  // Keyed by whichever identifier addressed the read, so a pinned picker and a
  // slug picker of the same valueset hold separate entries.
  const favouritesKey = [
    "valueset",
    pinnedValuesetId ?? system,
    facilityId,
    "favourites",
  ];
  const recentsKey = [
    "valueset",
    pinnedValuesetId ?? system,
    facilityId,
    "recents",
  ];

  const favouritesQuery = useQuery({
    queryKey: favouritesKey,
    queryFn: pinnedValuesetId
      ? query(valueSetApi.favourites, {
          pathParams: { id: pinnedValuesetId },
        })
      : query(valueSetApi.favouritesBySlug, {
          queryParams: { slug: system, facility: facilityId },
          // An unresolvable slug already surfaces through the search request.
          silent: true,
        }),
    enabled: !!pinnedValuesetId || !!system,
  });

  const addFavouriteMutation = useMutation({
    mutationFn: mutate(valueSetApi.addFavourite, {
      pathParams: { id: valuesetId ?? "" },
    }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: favouritesKey });
    },
  });

  const removeFavouriteMutation = useMutation({
    mutationFn: mutate(valueSetApi.removeFavourite, {
      pathParams: { id: valuesetId ?? "" },
    }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: favouritesKey });
      setItemToRemove(null);
    },
    onError: () => {
      setItemToRemove(null);
    },
  });

  const clearFavouritesMutation = useMutation({
    mutationFn: mutate(valueSetApi.clearFavourites, {
      pathParams: { id: valuesetId ?? "" },
    }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: favouritesKey });
      setShowBulkClearConfirm(false);
    },
    onError: () => {
      setShowBulkClearConfirm(false);
    },
  });

  const recentsQuery = useQuery({
    queryKey: recentsKey,
    queryFn: pinnedValuesetId
      ? query(valueSetApi.recentViews, {
          pathParams: { id: pinnedValuesetId },
        })
      : query(valueSetApi.recentViewsBySlug, {
          queryParams: { slug: system, facility: facilityId },
          silent: true,
        }),
    enabled: !!pinnedValuesetId || !!system,
  });

  const addRecentMutation = useMutation({
    mutationFn: mutate(valueSetApi.addRecentView, {
      pathParams: { id: valuesetId ?? "" },
    }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: recentsKey });
    },
  });

  // The starred column renders before the slug resolves, so every id-keyed
  // write has to be held back until there is an id to address.
  const canMutatePreferences = !!valuesetId;

  const seenCodes = new Set<string>();
  const searchResults = searchQuery.data?.results || [];
  const searchLower = search.toLowerCase();
  const recents =
    search.length >= 3
      ? (recentsQuery.data || []).filter(
          (r) =>
            r.display?.toLowerCase().includes(searchLower) ||
            r.code?.toLowerCase().includes(searchLower),
        )
      : recentsQuery.data || [];
  const resultsWithRecents = [...recents, ...searchResults].filter((item) => {
    if (seenCodes.has(item.code)) return false;
    seenCodes.add(item.code);
    return true;
  });
  // Filter favourites based on search
  const favourites = favouritesQuery.data?.filter((favourite) =>
    favourite.display?.toLowerCase().includes(searchLower),
  );

  return (
    <Command filter={() => 1}>
      <div className="p-3 border-b border-gray-200 flex justify-between items-center md:hidden">
        {title && <h3 className="text-base font-semibold">{title}</h3>}
        <Tabs
          value={activeTab.toString()}
          onValueChange={(value) => {
            setActiveTab(Number(value));
          }}
          className="md:hidden"
        >
          <TabsList className="flex w-full">
            <TabsTrigger value={"0"} className="flex-1">
              {t("search")}
            </TabsTrigger>
            <TabsTrigger value={"1"} className="flex-1">
              {t("starred")}
            </TabsTrigger>
          </TabsList>
        </Tabs>
      </div>
      <div className="border-b border-gray-200">
        <CommandInput
          placeholder={placeholder}
          className="outline-hidden border-none ring-0 shadow-none text-base sm:text-sm"
          onValueChange={onSearchChange}
          value={search}
          autoFocus={!isIOSDevice}
        />
      </div>
      <CommandList className="overflow-y-auto max-h-[55dvh] md:max-h-[35dvh] lg:max-h-[40dvh]">
        {!searchQuery.isFetching && (
          <CommandEmpty>
            {search.length < 3 ? (
              <p className="p-4 text-sm text-gray-500">
                {t("min_char_length_error", { min_length: 3 })}
              </p>
            ) : (
              <p className="p-4 text-sm text-gray-500">
                {t("no_results_found")}
              </p>
            )}
          </CommandEmpty>
        )}
        <div className="flex">
          <div
            data-testid="valueset-search-results"
            className={cn(
              activeTab === 0 ? "block" : "hidden",
              "md:block flex-1",
            )}
          >
            {searchQuery.isFetching ? (
              <div className="h-72 flex justify-center items-center py-6 text-gray-500">
                <Loader2 className="h-5 w-5 animate-spin mr-2" />
                {t("searching")}
              </div>
            ) : (
              <CommandGroup>
                {resultsWithRecents.map((option) => (
                  <Item
                    key={option.code}
                    option={option}
                    showCode={showCode}
                    search={search}
                    onSelect={() => {
                      const { primary } = getBestMatchDisplay(option, search);
                      onSelect({
                        code: option.code,
                        display: primary || option.display || "",
                        system: option.system || "",
                      });
                      if (canMutatePreferences) {
                        addRecentMutation.mutate(option);
                      }
                    }}
                    disableFavourite={!canMutatePreferences}
                    onFavourite={() => {
                      const isFavorited = favouritesQuery.data?.find(
                        (favourite) => favourite.code === option.code,
                      );
                      if (isFavorited) {
                        setItemToRemove(option);
                      } else {
                        addFavouriteMutation.mutate(option);
                      }
                    }}
                    isFavourite={
                      !!favouritesQuery.data?.find(
                        (favourite) => favourite.code === option.code,
                      )
                    }
                  />
                ))}
              </CommandGroup>
            )}
          </div>

          <div
            data-testid="valueset-starred"
            className={cn(
              activeTab === 1 ? "block" : "hidden",
              "md:block flex-1",
              (search.length < 3 && !searchQuery.isFetching) ||
                (!favourites?.length && !resultsWithRecents.length)
                ? ""
                : "md:border-l",
              "border-gray-200",
            )}
          >
            <CommandGroup>
              <div className="flex items-center justify-between">
                <span className="text-xs font-normal text-gray-700 p-1">
                  {t("starred")}
                </span>
                {favouritesQuery.data && favouritesQuery.data.length > 0 && (
                  <Button
import { useMutation } from "@tanstack/react-query";
import { CheckCircle2, LoaderCircle, SearchCheck, Trash2 } from "lucide-react";
import { useEffect, useId, useRef } from "react";
import { useWatch, type UseFormReturn } from "react-hook-form";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { cn } from "@/lib/utils";

import { Button } from "@/components/ui/button";
import {
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";

import valueSetApi from "@/types/valueSet/valueSetApi";
import { callApi } from "@/Utils/request/query";
import { HTTPError } from "@/Utils/request/types";

import type { ValueSetFormData } from "./ValueSetForm";

type ConceptFieldName =
  `compose.${"include" | "exclude"}.${number}.concept.${number}`;

interface CodeLookup {
  code: string;
  system: string;
  name: ConceptFieldName;
  signal: AbortSignal;
}

interface CodingFieldProps {
  system: string;
  name: ConceptFieldName;
  form: UseFormReturn<ValueSetFormData>;
  className?: string;
  disabled?: boolean;
  onRemove?: () => void;
  removeDisabled?: boolean;
}

export const CodingField = ({
  system,
  name,
  form,
  className,
  disabled,
  onRemove,
  removeDisabled,
}: CodingFieldProps) => {
  const { t } = useTranslation();
  const errorId = useId();
  const requestController = useRef<AbortController | null>(null);
  const code = useWatch({ control: form.control, name: `${name}.code` });
  const display = useWatch({ control: form.control, name: `${name}.display` });
  const isVerified = Boolean(display?.trim());
  const {
    mutate: lookup,
    isPending,
    isError,
    variables,
    reset: resetLookup,
  } = useMutation({
    mutationFn: async ({ code, system, signal }: CodeLookup) => {
      try {
        const response = await callApi(valueSetApi.lookup, {
          body: { system, code: code.trim() },
          signal,
          silent: true,
        });
        if (!response.metadata?.display?.trim()) {
          throw new Error("The terminology service returned no display name");
        }
        return response;
      } catch (error) {
        // Network errors and cancelled fetches are plain Errors in callApi.
        // Keep their feedback in this row instead of showing a global toast.
        if (error instanceof HTTPError) throw error;
        throw new HTTPError({
          message:
            error instanceof Error ? error.message : "Code lookup failed",
          status: 0,
          silent: true,
        });
      }
    },
    onSuccess: (response, request) => {
      // A removed row, changed system, or edited code must never receive the
      // display name from an earlier lookup (including an earlier row index).
      if (
        request.signal.aborted ||
        form.getValues(`${request.name}.code`) !== request.code
      ) {
        return;
      }
      form.setValue(`${request.name}.code`, request.code.trim(), {
        shouldDirty: true,
        shouldValidate: true,
      });
      form.setValue(`${request.name}.display`, response.metadata.display, {
        shouldDirty: true,
        shouldValidate: true,
      });
      toast.success(t("code_verified_successfully"));
    },
  });

  useEffect(() => {
    return () => requestController.current?.abort();
  }, [code, disabled, name, system]);

  const isCurrentLookup =
    variables?.name === name &&
    variables?.code === code &&
    variables?.system === system &&
    !variables.signal.aborted;
  const isLookupPending = isPending && isCurrentLookup;
  const lookupFailed = isError && isCurrentLookup && !isVerified;

  const handleVerify = () => {
    const currentCode = form.getValues(`${name}.code`);
    if (
      disabled ||
      isVerified ||
      isLookupPending ||
      !system ||
      !currentCode?.trim()
    ) {
      return;
    }

    requestController.current?.abort();
    requestController.current = new AbortController();
    lookup({
      system,
      code: currentCode,
      name,
      signal: requestController.current.signal,
    });
  };

  const handleCodeChange = () => {
    requestController.current?.abort();
    resetLookup();
    form.setValue(`${name}.display`, "", {
      shouldDirty: true,
      shouldValidate: true,
    });
  };
  return (
    <div
      className={cn(
        "grid gap-2 sm:grid-cols-[minmax(0,0.8fr)_minmax(0,1.2fr)_auto_auto] sm:items-start",
        className,
      )}
    >
      <FormField
        control={form.control}
        name={`${name}.code`}
        render={({ field, fieldState }) => (
          <FormItem>
            <FormLabel className="sr-only">{t("code")}</FormLabel>
            <FormControl>
              <Input
                {...field}
                placeholder={t("code")}
                disabled={disabled}
                aria-invalid={lookupFailed || fieldState.invalid}
                aria-errormessage={lookupFailed ? errorId : undefined}
                onChange={(event) => {
                  field.onChange(event);
                  handleCodeChange();
                }}
                onKeyDown={(event) => {
                  if (event.key === "Enter") {
                    event.preventDefault();
                    handleVerify();
                  }
                }}
              />
            </FormControl>
            <FormMessage />
          </FormItem>
        )}
      />
      <FormField
        control={form.control}
        name={`${name}.display`}
        render={({ field }) => (
          <FormItem>
            <FormLabel className="sr-only">{t("display_name")}</FormLabel>
            <FormControl>
              <Input
                {...field}
                placeholder={t("unverified")}
                className={cn("bg-gray-50", !field.value && "text-gray-500")}
                readOnly
                disabled={disabled}
              />
            </FormControl>
            <FormMessage />
          </FormItem>
        )}
      />
      <div className="flex justify-end gap-2 sm:contents">
        <Button
          aria-label={
            isVerified
              ? t("code_verified")
              : `${t("verify")} ${t("code").toLocaleLowerCase()}`
          }
          type="button"
          variant="outline"
          size="sm"
          onClick={handleVerify}
          disabled={
            disabled ||
            isLookupPending ||
            isVerified ||
            !system ||
            !code?.trim()
          }
          className={cn(
            "h-11 shrink-0 bg-white sm:h-10",
            isVerified
              ? "border-primary-200 bg-primary-100/60 text-primary-800 disabled:opacity-100"
              : "hover:border-gray-400 hover:bg-gray-100",
          )}
        >
          {isVerified ? (
            <>
              <CheckCircle2 className="size-4" />
              <span>{t("code_verified")}</span>
            </>
          ) : (
            <>
              {isLookupPending ? (
                <LoaderCircle className="size-4 animate-spin" />
              ) : (
                <SearchCheck className="size-4" />
              )}
              <span>
                {isLookupPending
                  ? t("verifying")
                  : lookupFailed
                    ? t("try_again")
                    : t("verify")}
              </span>
            </>
          )}
        </Button>
        {onRemove && (
          <Button
            type="button"
            variant="ghost"
            size="icon"
            aria-label={t("remove")}
            onClick={onRemove}
            disabled={disabled || removeDisabled}
            className="size-11 shrink-0 text-gray-500 hover:text-red-600 sm:size-10"
          >
            <Trash2 className="size-4" />
          </Button>
        )}
      </div>
      {lookupFailed && (
        <p
          id={errorId}
          role="alert"
          className="text-sm text-red-600 sm:col-span-4"
        >
          {t("valueset_code_verification_failed")}
        </p>
      )}
    </div>
  );
};
