import { faker } from "@faker-js/faker";
import { expect, test } from "@playwright/test";
import { getFieldErrorMessage } from "tests/helper/error";
import { expectToast } from "tests/helper/ui";
import { expectedSlug } from "tests/helper/utils";
import {
  LOINC_CODE_NAME,
  MAX_SLUG_LENGTH,
  MIN_SLUG_LENGTH,
  SNOMED_CODE_NAME,
  STATUS_OPTIONS,
  SYSTEM_OPTIONS,
  UCUM_CODE_NAME,
  VALID_LOINC_CODES,
  VALID_SNOMED_CODES,
  VALID_UCUM_CODES,
} from "./valuesetConstants";

test.use({ storageState: "tests/.auth/user.json" });

let name: string;
let slug: string;
let status: string;
let description: string;
let code: string;
let system: string;
let codeName: string;

test.describe("ValueSet Create", () => {
  test.beforeEach(async ({ page }) => {
    await page.goto("/admin/valuesets");
    name = faker.commerce.productName();
    slug = expectedSlug(name);
    description = faker.lorem.sentence();
    status = faker.helpers.arrayElement(STATUS_OPTIONS);
    system = faker.helpers.arrayElement(SYSTEM_OPTIONS);
    switch (system) {
      case "SNOMED":
        code = faker.helpers.arrayElement(VALID_SNOMED_CODES);
        codeName = SNOMED_CODE_NAME[code];
        break;
      case "LOINC":
        code = faker.helpers.arrayElement(VALID_LOINC_CODES);
        codeName = LOINC_CODE_NAME[code];
        break;
      case "UCUM":
        code = faker.helpers.arrayElement(VALID_UCUM_CODES);
        codeName = UCUM_CODE_NAME[code];
        break;
    }
  });

  test("create valueset with all fields and verify it appears in preview and list", async ({
    page,
  }) => {
    await page.getByRole("link", { name: "Create ValueSet" }).click();

    // Input details for the ValueSet
    await page.getByRole("textbox", { name: "Name *" }).fill(name);
    await page.getByRole("textbox", { name: "Slug *" }).fill(slug);
    await page.getByRole("textbox", { name: "Description" }).fill(description);
    await page.getByRole("combobox", { name: "Status *" }).click();
    await page.getByRole("option", { name: status }).click();
    await page.getByRole("button", { name: "Add Rule" }).first().click();
    await page.getByRole("combobox", { name: "System" }).click();
    await page.getByRole("option", { name: system }).click();
    await page.getByRole("button", { name: "Add Concept" }).click();
    await page.getByRole("textbox", { name: "Code" }).fill(code);
    await page.getByLabel("Verify code").click();

    await expect(
      page
        .getByRole("listitem")
        .filter({ hasText: "Code verified successfully" }),
    ).toBeVisible();

    // Verify the code name is present in the display value
    const displayValue = await page
      .getByRole("textbox", { name: "Display name" })
      .inputValue();
    expect(displayValue).toContain(codeName);

    await page.getByRole("button", { name: /valueset preview/i }).click();

    await expect(
      page.getByRole("dialog", {
        name: /valueset preview/i,
      }),
    ).toBeVisible();

    const previewDialog = page.getByRole("dialog", {
      name: /valueset preview/i,
    });

    await expect(previewDialog.getByRole("status")).toHaveText(
      /^Showing \d+ concepts?$/,
    );
    const previewConcept = previewDialog
      .getByRole("listitem")
      .filter({ hasText: codeName });
    await expect(previewConcept).toBeVisible();
    await expect(previewConcept.getByText(code, { exact: true })).toBeVisible();
    await previewDialog.getByRole("button", { name: "Close" }).click();

    const [createRequest] = await Promise.all([
      page.waitForRequest(
        (request) =>
          request.method() === "POST" &&
          new URL(request.url()).pathname === "/api/v1/valueset/",
      ),
      page.getByRole("button", { name: "Save ValueSet" }).click(),
    ]);
    expect(createRequest.postDataJSON()).toMatchObject({
      disable_composition: false,
    });

    await expectToast(page, /valueset created successfully/i);

    // Filter by status to find the created ValueSet
    await page.getByRole("tab", { name: status }).click();

    await page.getByRole("textbox", { name: "Search ValueSets" }).fill(name);

    // Verify the created valueset appears in the list
    await expect(page.getByRole("cell", { name: name })).toBeVisible();
    await expect(page.getByRole("cell", { name: description })).toBeVisible();
    await expect(page.getByRole("cell", { name: status })).toBeVisible();
  });

  test("verify slug auto-generation from title", async ({ page }) => {
    await page.getByRole("link", { name: "Create ValueSet" }).click();
    await page.getByRole("textbox", { name: "Name *" }).fill(name);

    const slugField = page.getByRole("textbox", { name: "Slug *" });
    const slugValue = await slugField.inputValue();
    expect(slugValue).toBeTruthy();
    expect(slugValue.length).toBeGreaterThan(0);

    const expectedSlugValue = expectedSlug(name);

    expect(slugValue).toContain(expectedSlugValue);
  });

  test("verify excluded rules are not present in preview", async ({ page }) => {
    await page.getByRole("link", { name: "Create ValueSet" }).click();

    // Input details for the ValueSet
    await page.getByRole("textbox", { name: "Name *" }).fill(name);
    await page.getByRole("textbox", { name: "Slug *" }).fill(slug);
    await page.getByRole("button", { name: "Add Rule" }).nth(1).click();
    await page.getByRole("combobox", { name: "System" }).click();
    await page.getByRole("option", { name: system }).click();
    await page.getByRole("button", { name: "Add Concept" }).click();
    await page.getByRole("textbox", { name: "Code" }).fill(code);
    await page.getByLabel("Verify code").click();

    await expect(
      page
        .getByRole("listitem")
        .filter({ hasText: "Code verified successfully" }),
    ).toBeVisible();

    // Verify the code name is present in the display value
    const displayValue = await page
      .getByRole("textbox", { name: "Display name" })
      .inputValue();
    expect(displayValue).toContain(codeName);

    await page.getByRole("button", { name: /valueset preview/i }).click();

    await expect(
      page.getByRole("dialog", {
        name: /valueset preview/i,
      }),
    ).toBeVisible();

    const previewDialog = page.getByRole("dialog", {
      name: /valueset preview/i,
    });

    await previewDialog
      .getByRole("textbox", { name: "Search for a concept in this valueset" })
      .fill(code);
    await expect(previewDialog.getByRole("status")).toHaveText(
      /^Showing \d+ concepts?$/,
    );
    await expect(
      previewDialog.getByRole("listitem").getByText(code, { exact: true }),
    ).toHaveCount(0);
    await previewDialog.getByRole("button", { name: "Close" }).click();
import { expect, test } from "@playwright/test";
import {
  KITCHEN_SINK_FACILITY_SLUG,
  KITCHEN_SINK_INSTANCE_SLUG,
} from "tests/helper/questionnaireV2";
import { getFacilityId } from "tests/support/facilityId";

test.use({ storageState: "tests/.auth/user.json" });

/**
 * Per-mount scoping: the admin mount lists instance questionnaires only and
 * the facility mount lists that facility's questionnaires only — pinned via
 * the two kitchen-sink fixtures, which share a searchable title prefix but
 * live in different auth contexts.
 */
test.describe("Questionnaire v2 per-mount scoping", () => {
  test("facility-scoped questionnaires are absent from the admin list and vice versa", async ({
    page,
  }) => {
    const facilityId = getFacilityId();
    const tableBody = page.locator('[data-slot="table-body"]');

    await test.step("Admin list shows the instance fixture only", async () => {
      await page.goto("/admin/questionnaires");
      await page
        .getByPlaceholder("Search Questionnaires")
        .fill("E2E Kitchen Sink");
      await expect(tableBody).toContainText(KITCHEN_SINK_INSTANCE_SLUG);
      await expect(tableBody).not.toContainText(KITCHEN_SINK_FACILITY_SLUG);
    });

    await test.step("Facility list shows the facility fixture only", async () => {
      await page.goto(`/facility/${facilityId}/settings/questionnaires`);
      await page
        .getByPlaceholder("Search Questionnaires")
        .fill("E2E Kitchen Sink");
      await expect(tableBody).toContainText(KITCHEN_SINK_FACILITY_SLUG);
      await expect(tableBody).not.toContainText(KITCHEN_SINK_INSTANCE_SLUG);
    });
  });

  test("subject-type options differ per mount (patient is admin-only)", async ({
    page,
  }) => {
    const facilityId = getFacilityId();

    await test.step("Admin create offers all five subject types", async () => {
      await page.goto("/admin/questionnaires/new");
      const group = page.getByRole("radiogroup", { name: "Subject Type" });
      await expect(group.getByRole("radio")).toHaveCount(5);
      for (const label of [
        "Patient",
        "Encounter",
        "Location",
        "Device",
        "Facility",
      ]) {
        await expect(
          group.getByRole("radio", { name: label, exact: true }),
        ).toBeVisible();
      }
    });

    await test.step("Facility create omits the Patient subject type", async () => {
      await page.goto(`/facility/${facilityId}/settings/questionnaires/new`);
      const group = page.getByRole("radiogroup", { name: "Subject Type" });
      await expect(group.getByRole("radio")).toHaveCount(4);
      await expect(
        group.getByRole("radio", { name: "Patient", exact: true }),
      ).not.toBeVisible();
      for (const label of ["Encounter", "Location", "Device", "Facility"]) {
        await expect(
          group.getByRole("radio", { name: label, exact: true }),
        ).toBeVisible();
      }
    });
  });
});
