type ButtonProps = Omit<React.ComponentProps<typeof Button>, keyof Props>;

interface Props {
  system: string;
  /** Pins the lookup to one exact valueset, bypassing slug resolution. */
  valuesetId?: string;
  value?: Code | null;
  onSelect: (value: Code) => void;
  placeholder?: string;
  count?: number;
  searchPostFix?: string;
  hideTrigger?: boolean;
  controlledOpen?: boolean;
  showCode?: boolean;
  title?: string;
  closeOnSelect?: boolean;
  mobileTrigger?: React.ReactNode;
}

export default function ValueSetSelect({
  system,
  valuesetId,
  value,
  onSelect,
  placeholder = "Search...",
  count = 10,
  searchPostFix = "",
  hideTrigger = false,
  controlledOpen = false,
  closeOnSelect = true,
  showCode = false,
  title,
  mobileTrigger,
  ...props
}: Props & ButtonProps) {
  const { t } = useTranslation();
  const [internalOpen, setInternalOpen] = useState(false);
  const [search, setSearch] = useState("");
  const isMobile = useBreakpoints({ default: true, sm: false });
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (controlledOpen || internalOpen) {
      setSearch("");
    }
  }, [controlledOpen, internalOpen]);

  useEffect(() => {
    if (internalOpen && isMobile) {
      const timer = setTimeout(() => {
        inputRef.current?.focus();
      }, 200);
      return () => clearTimeout(timer);
    }
  }, [internalOpen, isMobile]);
  if (isMobile && !hideTrigger) {
    return (
      <Drawer
        open={internalOpen || controlledOpen}
        onOpenChange={setInternalOpen}
      >
        <DrawerTrigger asChild>
          {mobileTrigger ? (
            mobileTrigger
          ) : (
            <Button
              variant="white"
              role="combobox"
              className={cn(
                "w-full flex justify-between h-auto whitespace-normal text-left font-normal border-gray-300 shadow-xs",
                !value?.display && "text-gray-500 hover:bg-white",
              )}
              {...props}
            >
              <span>
"}

