import { useQuery } from "@tanstack/react-query";
import { useTranslation } from "react-i18next";

import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

import {
  TagConfig,
  TagResource,
  getTagHierarchyDisplay,
} from "@/types/emr/tagConfig/tagConfig";
import tagConfigApi from "@/types/emr/tagConfig/tagConfigApi";
import query from "@/Utils/request/query";

interface TagConfigParamPickerProps {
  id: string;
  resource: TagResource;
  /** The studio mount's facility — facility tags are listed alongside
   *  instance ones; an instance mount lists instance tags only. */
  facilityId?: string;
  value: unknown;
  onChange: (value: unknown) => void;
  "aria-label": string;
}

/**
 * The control an instruction param gets when its schema carries
 * `x-care-picker: tag_config` — a tag chosen from the active tag configs
 * for `x-care-resource`, stored as the tag's id (what the backend's
 * tag instructions take).
 */
export function TagConfigParamPicker({
  id,
  resource,
  facilityId,
  value,
  onChange,
  "aria-label": ariaLabel,
}: TagConfigParamPickerProps) {
  const { t } = useTranslation();
  const { data, isLoading } = useQuery({
    queryKey: ["tags", resource, "action-picker", facilityId],
    queryFn: query.paginated(tagConfigApi.list, {
      queryParams: {
        resource,
        status: "active",
        ...(facilityId && { facility: facilityId }),
      },
    }),
  });
  const tags = data?.results ?? [];
  const selectableTags = tags.filter((tag) => !tag.has_children);
  const groups = new Map<string, { label: string; tags: TagConfig[] }>();
  for (const tag of selectableTags) {
    const key = tag.parent?.id ?? "";
    const group = groups.get(key) ?? {
      label: tag.parent
        ? getTagHierarchyDisplay(
            { ...tag, display: tag.parent.display, parent: tag.parent.parent },
            " › ",
          )
        : "",
      tags: [],
    };
    group.tags.push(tag);
    groups.set(key, group);
  }
  const stored = typeof value === "string" ? value : undefined;
  const unknownStored =
    !!stored && !isLoading && !selectableTags.some((tag) => tag.id === stored);

  return (
    <div className="space-y-1">
      <Select value={stored} onValueChange={(next) => onChange(next)}>
        <SelectTrigger
          id={id}
          className="w-full"
          aria-label={ariaLabel}
          aria-invalid={unknownStored}
        >
          <SelectValue
            placeholder={isLoading ? t("loading") : t("select_tag")}
          />
        </SelectTrigger>
        <SelectContent>
          {/* A stored tag the list no longer carries (archived, other
              facility) stays visible so the author sees what to replace. */}
          {unknownStored && (
            <SelectItem value={stored} disabled className="text-red-600">
              {t("action_tag_unknown")}
            </SelectItem>
          )}
          {Array.from(groups, ([key, group]) => (
            <SelectGroup key={key}>
              {group.label && <SelectLabel>{group.label}</SelectLabel>}
              {group.tags.map((tag) => (
                <SelectItem key={tag.id} value={tag.id}>
                  {tag.display}
                </SelectItem>
              ))}
            </SelectGroup>
          ))}
        </SelectContent>
      </Select>
      {!isLoading && selectableTags.length === 0 && (
        <p className="text-xs text-gray-500">{t("action_tag_picker_empty")}</p>
      )}
    </div>
  );
}
import {
  ArrowDown,
  ArrowUp,
  Copy,
  EyeOff,
  Plus,
  Split,
  Trash2,
  TriangleAlert,
} from "lucide-react";
import { Dispatch, createContext, useContext, useEffect, useMemo } from "react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { BuilderAction } from "@/components/QuestionnaireV2/builder/builderReducer";
import {
  FormChrome,
  QuestionShellProps,
} from "@/components/QuestionnaireV2/form/chrome";
import { QuestionnaireFormCanvas } from "@/components/QuestionnaireV2/form/FormCanvas";

import { Input } from "@/components/ui/input";

import { Question } from "@/types/questionnaire/question";

import { questionsByLinkId, shortConditionSummary } from "./conditionSummary";

interface StudioCanvasContextValue {
  editing: boolean;
  selectedId: string | null;
  onSelectQuestion: (id: string) => void;
  dispatch: Dispatch<BuilderAction>;
  /** link_id → question, one build per tree change — the logic chips
   *  resolve enable_when targets from it, per block, on every render. */
  conditionTargets: ReadonlyMap<string, Question>;
  /** question id → save-rule i18n key, from findInvalidQuestions. */
  issueKeysByQuestionId: ReadonlyMap<string, string>;
}

const StudioCanvasContext = createContext<StudioCanvasContextValue | null>(
  null,
);

function useStudioCanvas(): StudioCanvasContextValue {
  const context = useContext(StudioCanvasContext);
  if (!context) {
    throw new Error("Studio chrome rendered outside StudioCanvas");
  }
  return context;
}

/**
 * The selection chrome injected into the form renderer's decoration seam.
 * Module-level components (never recreated per render) — a per-render
 * component identity would remount the whole canvas subtree on every
 * selection change.
 */
function StudioQuestionShell({
  question,
  index,
  siblingCount,
  depth,
  hiddenByLogic,
  children,
}: QuestionShellProps) {
  const { t } = useTranslation();
  const studio = useStudioCanvas();

  const hiddenBadge = (
    <span className="pointer-events-none absolute -top-2.5 right-3 z-10 flex items-center gap-1 rounded bg-amber-100 px-2 py-0.5 text-[10px] font-semibold text-amber-800">
      <EyeOff className="size-3" />
      {t("hidden_by_conditions")}
    </span>
  );

  // Preview mode renders the plain form.
  if (!studio.editing) return <>{children}</>;

  // Deep nesting (inside nested groups) is edited from the
  // outline/inspector, not decorated in place — but the logic-hidden cue
  // still applies, or a revealed deep question would look like a normal one.
  if (depth >= 2) {
    if (!hiddenByLogic) return <>{children}</>;
    return (
      <div className="relative">
        {hiddenBadge}
        {children}
      </div>
    );
  }

  const selected = studio.selectedId === question.id;

  const toolbarButton = (
    label: string,
    Icon: typeof ArrowUp,
    onClick: () => void,
    options?: { disabled?: boolean; destructive?: boolean },
  ) => (
    <button
      type="button"
      aria-label={label}
      title={label}
      disabled={options?.disabled}
      onClick={(event) => {
        event.stopPropagation();
        onClick();
      }}
      className={cn(
        "flex size-7 items-center justify-center rounded-md text-gray-500 transition-colors disabled:opacity-40",
        options?.destructive
          ? "hover:bg-red-50 hover:text-red-600"
          : "hover:bg-gray-100 hover:text-gray-900",
      )}
    >
      <Icon className="size-3.5" />
    </button>
  );

  return (
    // The inner form content is `inert` on the edit canvas, so this wrapper
    // is the click target; keyboard selection goes through the outline tree,
    // which lists every question as a real button.
    <div
      onClick={(event) => {
        event.stopPropagation();
        studio.onSelectQuestion(question.id);
      }}
      className={cn(
        "relative cursor-pointer rounded-xl transition-shadow",
        selected
          ? "ring-2 ring-primary-600 ring-offset-2"
          : "hover:ring-1 hover:ring-gray-300 hover:ring-offset-2",
      )}
    >
      {selected && (
        <>
          <span
            aria-hidden
            className="pointer-events-none absolute -top-2.5 left-3 z-10 rounded bg-primary-700 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide text-white"
          >
            {t("editing")}
          </span>
          <div className="absolute -top-4 right-3 z-10 flex items-center gap-0.5 rounded-lg border border-gray-200 bg-white p-0.5 shadow-md">
            {toolbarButton(
              t("move_question_up"),
              ArrowUp,
              () =>
                studio.dispatch({
                  type: "moveQuestion",
                  id: question.id,
                  direction: "up",
                }),
              { disabled: index === 0 },
            )}
            {toolbarButton(
              t("move_question_down"),
              ArrowDown,
              () =>
                studio.dispatch({
                  type: "moveQuestion",
                  id: question.id,
                  direction: "down",
                }),
              { disabled: index === siblingCount - 1 },
            )}
            <span aria-hidden className="mx-0.5 h-4 w-px bg-gray-200" />
            {toolbarButton(t("duplicate_question"), Copy, () =>
              studio.dispatch({ type: "duplicateQuestion", id: question.id }),
            )}
            {toolbarButton(
              t("delete_question"),
              Trash2,
              () =>
                studio.dispatch({
                  type: "removeQuestions",
                  ids: [question.id],
                }),
              { destructive: true },
            )}
          </div>
        </>
      )}
      {hiddenByLogic && !selected && hiddenBadge}

