import { expect, test } from "@playwright/test";
import {
  addTopLevelQuestion,
  createQuestionnaireAndOpenBuilder,
} from "tests/helper/questionnaireV2";
import { expectToast } from "tests/helper/ui";
import { getFacilityId } from "tests/support/facilityId";

test.use({ storageState: "tests/.auth/user.json" });

/**
 * The studio's save-flow chrome: the issues popover, Discard, the Save
 * button's version chip and the outline search — affordances the redesign
 * introduced on top of the builder contracts.
 */
test.describe("Questionnaire v2 studio chrome", () => {
  test("issues popover lists save blockers and click-to-fix selects the question", async ({
    page,
  }) => {
    const facilityId = getFacilityId();
    const stamp = Date.now();

    await createQuestionnaireAndOpenBuilder(page, {
      basePath: `/facility/${facilityId}/settings/questionnaires`,
      title: `QV2 Chrome ${stamp}`,
    });

    await test.step("An untitled question surfaces as '1 to fix'", async () => {
      await page.getByRole("button", { name: "Add First Question" }).click();
      await expect(
        page.getByRole("button", { name: "1 to fix" }),
      ).toBeVisible();
    });

    await test.step("The popover entry names the rule and selects the question", async () => {
      await addTopLevelQuestion(page, `Named ${stamp}`);
      await page.getByRole("button", { name: "1 to fix" }).click();
      await page
        .getByRole("button", { name: "Every question needs a title" })
        .click();
      await expect(
        page.getByRole("textbox", { name: "Question Title" }),
      ).toHaveValue("");
    });

    await test.step("Fixing the issue restores 'Ready to save'", async () => {
      await page
        .getByRole("textbox", { name: "Question Title" })
        .pressSequentially(`Fixed ${stamp}`);
      await expect(
        page.getByRole("button", { name: "to fix" }),
      ).not.toBeVisible();
      await expect(page.getByText("Ready to save")).toBeVisible();
    });
  });

  test("Discard restores the saved draft and the Save chip shows the next version", async ({
    page,
  }) => {
    const facilityId = getFacilityId();
    const stamp = Date.now();
    const originalTitle = `Original ${stamp}`;
    const titleInput = page.getByRole("textbox", { name: "Question Title" });
    const saveButton = page.getByRole("button", { name: "Save Changes" });

    await createQuestionnaireAndOpenBuilder(page, {
      basePath: `/facility/${facilityId}/settings/questionnaires`,
      title: `QV2 Discard ${stamp}`,
    });
    await addTopLevelQuestion(page, originalTitle);

    await test.step("The Save chip shows the version the save will create", async () => {
      await expect(saveButton).toContainText("v2");
      await saveButton.click();
      await expectToast(page, "Questionnaire updated successfully");
      await expect(saveButton).toContainText("v3");
    });

    await test.step("Discard reverts unsaved edits and disables Save", async () => {
      await titleInput.fill(`Edited ${stamp}`);
      await expect(saveButton).toBeEnabled();
      await page.getByRole("button", { name: "Discard" }).click();
      await expect(titleInput).toHaveValue(originalTitle);
      await expect(saveButton).toBeDisabled();
    });
  });

  test("outline search filters rows and hides the insert separators", async ({
    page,
  }) => {
    const facilityId = getFacilityId();
    const stamp = Date.now();
    const nav = page.getByRole("navigation");

    await createQuestionnaireAndOpenBuilder(page, {
      basePath: `/facility/${facilityId}/settings/questionnaires`,
      title: `QV2 Search ${stamp}`,
    });
    for (const title of [`Alpha ${stamp}`, `Beta ${stamp}`, `Gamma ${stamp}`]) {
      await addTopLevelQuestion(page, title);
    }

    const search = page.getByPlaceholder("Find a question…");
    const navAddButtons = nav.getByRole("button", { name: "Add new question" });

    await test.step("A query narrows the outline to matching rows", async () => {
      // Unfiltered: two insert separators (between 3 rows) + the footer.
      await expect(navAddButtons).toHaveCount(3);
      await search.fill("Beta");
      await expect(
        nav.getByRole("button", { name: `Beta ${stamp}` }),
      ).toBeVisible();
      await expect(
        nav.getByRole("button", { name: `Alpha ${stamp}` }),
      ).not.toBeVisible();
      // Insert separators are positional in the filtered list — they hide
      // while a filter is active so an insert can't land at the wrong
      // index; the footer add stays reachable.
      await expect(navAddButtons).toHaveCount(1);
    });

    await test.step("No matches shows the empty message but keeps the footer adds", async () => {
      await search.fill("zzz-no-match");
      await expect(
        page.getByText("No question matches that search."),
      ).toBeVisible();
      await expect(
        nav.getByRole("button", { name: "Add Section" }),
      ).toBeVisible();
    });

    await test.step("Clearing the query restores every row", async () => {
      await search.fill("");
      for (const title of [
        `Alpha ${stamp}`,
        `Beta ${stamp}`,
        `Gamma ${stamp}`,
      ]) {
        await expect(nav.getByRole("button", { name: title })).toBeVisible();
      }
    });
  });
});
import { expect, type Locator, type Page } from "@playwright/test";

export async function selectFromLocationMultiSelect(
  page: Page,
  trigger: Locator,
  {
    search,
    itemIndex = 0,
    closeAfterSelect = true,
  }: { search?: string; itemIndex?: number; closeAfterSelect?: boolean } = {},
) {
  await trigger.waitFor({ state: "visible" });
  await trigger.scrollIntoViewIfNeeded();
  await trigger.click();

  const scope = page
    .locator("[role='dialog'], [data-radix-popper-content-wrapper]")
    .last();
  await scope.waitFor();

  if (search) {
    const input = scope.getByPlaceholder(/search locations/i);
    if (await input.isVisible().catch(() => false)) {
      await input.fill("");
      await input.fill(search);
    }
  }

  const plusButtons = scope.locator("button:has(svg.lucide-plus)");
  await plusButtons.first().waitFor({ state: "visible" });
  await plusButtons.nth(itemIndex).click();

  if (closeAfterSelect) {
    // Try to close via focused scope first; fallback to toggling the trigger
    await scope.press("Escape").catch(() => {});
    const waitHidden = scope.waitFor({ state: "hidden" }).catch(() => null);
    await waitHidden;
    const stillVisible = await scope.isVisible().catch(() => false);
    if (stillVisible) {
      // Fallback: click the trigger again to toggle close
      await trigger.click().catch(() => {});
      await scope.waitFor({ state: "hidden" }).catch(() => {});
    }
  }
}

export async function closeAnyOpenPopovers(page: Page) {
  const poppers = page.locator("[data-radix-popper-content-wrapper]");
  for (let i = 0; i < 3; i += 1) {
    const visible = await poppers
      .first()
      .isVisible()
      .catch(() => false);
    if (!visible) break;
    await page.keyboard.press("Escape").catch(() => {});
    await poppers
      .first()
      .waitFor({ state: "hidden" })
      .catch(() => {});
  }
}

interface SelectFromRequirementsOptions {
  search?: string;
  itemIndex?: number;
}

/**
 * Helper for RequirementsSelector component (multi-select with Plus buttons)
 *
 * This component uses a Command interface where each option has a Plus button that must be clicked.
 * It's used for specimen requirements, observation requirements, etc.
 *
 * Key behavior:
 * - Multi-select (doesn't auto-close)
 * - Each option has a Plus button (button:has(svg.lucide-plus))
 * - Shows selected items count in trigger
 *
 * @example
 * await selectFromRequirements(page, specimenTrigger, { itemIndex: 0 });
 */
export async function selectFromRequirements(
  page: Page,
  trigger: Locator,
  { search, itemIndex = 0 }: SelectFromRequirementsOptions = {},
) {
  await trigger.waitFor({ state: "visible" });
  await trigger.scrollIntoViewIfNeeded();

  // Close any existing popovers before opening
  await closeAnyOpenPopovers(page);

  await trigger.click();

  // Wait for the picker to open (could be dialog or popover)
  const dialog = page.getByRole("dialog").last();
  const hasDialog = await dialog.isVisible().catch(() => false);
  const popper = page.locator("[data-radix-popper-content-wrapper]").last();
  const scope = hasDialog ? dialog : popper;

  await scope.waitFor({ state: "visible" });

  // If search is provided, use the search input
  if (search) {
    const input = scope.locator('[data-slot="command-input"]').first();
    if (await input.isVisible().catch(() => false)) {
      await input.fill("");
      await input.fill(search);
      await page.waitForTimeout(500); // Wait for debounced search
    }
  }

  // Wait for options to load
  const options = scope.getByRole("option");
  await options.first().waitFor({ state: "visible" });

  const count = await options.count();
  if (count === 0) {
    throw new Error("No options found in requirements selector");
  }

  // Find the Plus button inside the option at the specified itemIndex
  const targetOption = options.nth(itemIndex);
  const plusButton = targetOption.locator("button:has(svg.lucide-plus)");

  // Wait for the plus button and click it
  await plusButton.waitFor({ state: "visible" });
  await plusButton.click();

  // Wait for selection to register (multi-select, so it stays open)
  await page.waitForTimeout(300);
}

interface SelectFromValueSetOptions {
  search?: string;
  itemIndex?: number;
  tab?: "search" | "starred";
}

/**
 * Helper for ValueSetSelect component (single-select with search and favorites)
 *
 * This component uses ValueSetSearchContent with Command + Tabs (Search/Starred).
 * It's used for code selection like body site, diagnostic codes, etc.
 *
 * Key behavior:
 * - Single selection (auto-closes after select)
 * - Has Search and Starred tabs (mobile)
 * - Options are directly clickable CommandItems
 * - Shows "Searching..." state while loading
 *
 * @example
 * await selectFromValueSet(page, codeTrigger, { search: "test", itemIndex: 0 });
 */
export async function selectFromValueSet(
  page: Page,
  trigger: Locator,
  { search, itemIndex = 0, tab = "search" }: SelectFromValueSetOptions = {},
) {
  await trigger.waitFor({ state: "visible" });
  await trigger.scrollIntoViewIfNeeded();

  // Close any existing popovers before opening
  await closeAnyOpenPopovers(page);

  await trigger.click();

  // Wait for the picker to open (could be dialog or popover)
  const dialog = page.getByRole("dialog").last();
  const hasDialog = await dialog.isVisible().catch(() => false);
  const popper = page.locator("[data-radix-popper-content-wrapper]").last();
  const scope = hasDialog ? dialog : popper;

  await scope.waitFor({ state: "visible" });

  // Switch tabs if needed (mainly for mobile, but won't hurt on desktop)
  if (tab === "starred") {
    const starredTab = scope.getByRole("tab", { name: /starred/i });
    if (await starredTab.isVisible().catch(() => false)) {
      await starredTab.click();
      await page.waitForTimeout(200);
    }
  }

  // If search is provided, use the search input
  if (search) {
    const input = scope.locator('[data-slot="command-input"]').first();
    if (await input.isVisible().catch(() => false)) {
      await input.fill("");
      await input.fill(search);

      // Wait for "Searching..." to appear and disappear
      const searching = scope.getByText(/searching/i);
      if (await searching.isVisible().catch(() => false)) {
        await searching.waitFor({ state: "hidden" });
      }
    }
  }

  // Scope to the requested column. Both columns render role=option, and the
  // starred column stays mounted while a search is in flight, so an unscoped
  // query can resolve against a starred entry instead of a search result.
  const column = scope.getByTestId(
    tab === "starred" ? "valueset-starred" : "valueset-search-results",
  );
  const options = column.getByRole("option");
  await options.first().waitFor({ state: "visible" });

  const count = await options.count();
  if (count === 0) {
    throw new Error("No options found in value set selector");
  }

  // Click the option directly (not a button inside it)
  const targetOption = options.nth(itemIndex);
  await targetOption.click();

  // Auto-closes on selection, so wait for it to close
  await scope.waitFor({ state: "hidden" }).catch(() => {});
}

