      await expect(
        page.getByRole("textbox", { name: "Question Title" }),
      ).toHaveValue(importedQuestionOneText);
      await expect(
        page.getByRole("navigation").getByText(importedQuestionTwoText),
      ).toBeVisible();
    });

    await test.step("Clone the questionnaire from its detail page", async () => {
      // The studio's Back is a real link (middle-click / new-tab support).
      await page.getByRole("link", { name: "Back" }).click();
      await page.waitForURL(/\/settings\/questionnaires\/[0-9a-f-]+$/);

      await page.getByRole("button", { name: "Clone Questionnaire" }).click();
      const dialog = page.getByRole("dialog", { name: "Clone Questionnaire" });
      await expect(dialog).toBeVisible();
      await expect(dialog.getByRole("textbox", { name: "Title" })).toHaveValue(
        `${title} (Copy)`,
      );

      await dialog.getByRole("button", { name: "Clone Questionnaire" }).click();
      await expectToast(page, "Questionnaire cloned successfully");
      // The source detail URL already matches the generic detail pattern, so
      // a plain regex wait would resolve immediately without ever navigating
      // — wait for the URL to actually change to a different (new) detail id.
      await page.waitForURL(
        (url) =>
          url.toString() !== detailUrl &&
          /\/settings\/questionnaires\/[0-9a-f-]+$/.test(url.pathname),
      );
    });

    await test.step("The clone landed on a new detail page with the copied title and questions", async () => {
      expect(page.url()).not.toBe(detailUrl);
      await expect(page.getByRole("textbox", { name: "Title" })).toHaveValue(
        `${title} (Copy)`,
      );
      await expect(
        page
          .getByRole("radiogroup", { name: "Status" })
          .getByRole("radio", { name: "Draft" }),
      ).toHaveAttribute("aria-checked", "true");
      await expect(page.getByText(importedQuestionOneText)).toBeVisible();
      await expect(page.getByText(importedQuestionTwoText)).toBeVisible();
    });

    await test.step("The source questionnaire is unchanged", async () => {
      await page.goto(detailUrl);
      await expect(page.getByRole("textbox", { name: "Title" })).toHaveValue(
        title,
      );
      await expect(
        page
          .getByRole("radiogroup", { name: "Status" })
          .getByRole("radio", { name: "Active" }),
      ).toHaveAttribute("aria-checked", "true");
      await expect(page.getByText(importedQuestionOneText)).toBeVisible();
      await expect(page.getByText(importedQuestionTwoText)).toBeVisible();
    });
  });
});
import { zodResolver } from "@hookform/resolvers/zod";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { navigate } from "raviger";
import { useEffect, useMemo } from "react";
import { useForm } from "react-hook-form";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";

import { questionnaireKeys } from "@/components/QuestionnaireV2/queryKeys";
import { remapActionLinkIds } from "@/components/QuestionnaireV2/shared/actionExpression";
import { regenerateQuestionIdsWithMap } from "@/components/QuestionnaireV2/shared/questionTree";

import {
  QuestionnaireRead,
  QuestionnaireScope,
  scopeCreateFields,
} from "@/types/questionnaire/questionnaire";
import questionnaireApi from "@/types/questionnaire/questionnaireApi";
import mutate from "@/Utils/request/mutate";

import {
  SLUG_MAX_LENGTH,
  questionnaireBasicSchema,
} from "./questionnaireFormSchema";

const COPY_SUFFIX = "-copy";

/**
 * `{slug}-copy`, clamped so it still respects the shared slug length rule
 * even when the source slug is already near the SLUG_MAX_LENGTH ceiling —
 * truncates the base rather than the suffix so the result still reads as a
 * copy.
 */
function defaultCloneSlug(slug: string): string {
  const base = slug
    .slice(0, SLUG_MAX_LENGTH - COPY_SUFFIX.length)
    .replace(/-+$/, "");
  return `${base}${COPY_SUFFIX}`;
}

interface CloneFormValues {
  title: string;
  slug: string;
}

interface CloneQuestionnaireDialogProps {
  scope: QuestionnaireScope;
  questionnaire: QuestionnaireRead;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function CloneQuestionnaireDialog({
  scope,
  questionnaire,
  open,
  onOpenChange,
}: CloneQuestionnaireDialogProps) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();

  const cloneSchema = useMemo(
    () => questionnaireBasicSchema(t).pick({ title: true, slug: true }),
    [t],
  );

  const form = useForm<CloneFormValues>({
    resolver: zodResolver(cloneSchema),
    defaultValues: {
      title: t("cloned_questionnaire_title", { title: questionnaire.title }),
      slug: defaultCloneSlug(questionnaire.slug),
    },
  });

  // Re-seed the defaults every time the dialog opens — the form stays
  // mounted between opens, and the underlying questionnaire's title/slug
  // may have changed (e.g. the detail form was edited) since the last time.
  useEffect(() => {
    if (open) {
      form.reset({
        title: t("cloned_questionnaire_title", { title: questionnaire.title }),
        slug: defaultCloneSlug(questionnaire.slug),
      });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, questionnaire.title, questionnaire.slug]);

  const { mutate: clone, isPending } = useMutation({
    mutationFn: mutate(questionnaireApi.createV2),
    onSuccess: (created: QuestionnaireRead) => {
      queryClient.invalidateQueries({ queryKey: questionnaireKeys.all });
      toast.success(t("questionnaire_cloned_successfully"));
      onOpenChange(false);
      navigate(`${scope.basePath}/${created.id}`);
    },
  });

  const onSubmit = (values: CloneFormValues) => {
    const regenerated = regenerateQuestionIdsWithMap(
      structuredClone(questionnaire.questions),
    );
    clone({
      title: values.title,
      slug: values.slug,
      description: questionnaire.description,
      version: questionnaire.version ? String(questionnaire.version) : "1.0",
      code: questionnaire.code,
      status: "draft",
      subject_type: questionnaire.subject_type,
      questions: regenerated.questions,
      // Actions name answers by link_id, and every link_id was just
      // regenerated — follow the map so the copy's automations still point
      // at the copy's questions.
      actions: remapActionLinkIds(
        questionnaire.actions ?? [],
        regenerated.linkIdMap,
      ),
      ...scopeCreateFields(scope),
    });
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>{t("clone_questionnaire")}</DialogTitle>
          <DialogDescription>
            {t("clone_questionnaire_draft_description")}
          </DialogDescription>
        </DialogHeader>
        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
            <FormField
              control={form.control}
              name="title"
              render={({ field }) => (
                <FormItem>
                  <FormLabel aria-required>{t("title")}</FormLabel>
                  <FormControl>
                    <Input {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
            <FormField
              control={form.control}
              name="slug"
              render={({ field }) => (
                <FormItem>
                  <FormLabel aria-required>{t("slug")}</FormLabel>
                  <FormControl>
                    <Input {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
            <DialogFooter>
              <Button
                type="button"
                variant="outline"
                onClick={() => onOpenChange(false)}
              >
                {t("cancel")}
              </Button>
              <Button type="submit" disabled={isPending}>
                {t("clone_form")}
              </Button>
            </DialogFooter>
          </form>
        </Form>
      </DialogContent>
    </Dialog>
  );
}
"}

