import { z } from "zod";

import { QUESTION_TYPES, Question } from "@/types/questionnaire/question";
import { SUBJECT_TYPES } from "@/types/questionnaire/questionnaire";

/**
 * Recursively narrows an unknown question-ish object down to the fields the
 * importer needs. Validation must recurse: nested `questions` reach the
 * builder tree and the PUT body unmodified, so a malformed child (missing
 * `text`, or `questions` that isn't an array) would otherwise surface as a
 * crash in the confirm step or a save that silently does nothing.
 */
function isQuestionLike(value: unknown): value is Question {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as {
    text?: unknown;
    type?: unknown;
    link_id?: unknown;
    questions?: unknown;
  };
  if (typeof candidate.text !== "string") return false;
  // Membership, not just typeof: an unknown `type` (e.g. "radio") would flow
  // into builder state and crash the type picker's TYPE_ICONS lookup, then
  // be PUT to the API on save.
  if (
    typeof candidate.type !== "string" ||
    !(QUESTION_TYPES as readonly string[]).includes(candidate.type)
  ) {
    return false;
  }
  // link_id is optional (regenerateQuestionIds synthesizes fresh ones), but
  // when present it must be a string.
  if (
    candidate.link_id !== undefined &&
    typeof candidate.link_id !== "string"
  ) {
    return false;
  }
  if (candidate.questions !== undefined) {
    if (!Array.isArray(candidate.questions)) return false;
    return candidate.questions.every(isQuestionLike);
  }
  return true;
}

/**
 * Accepts either a bare `{ questions: [...] }` payload or a full
 * questionnaire export (which has a `questions` array alongside its other
 * fields) — both shapes are read the same way, through `.questions`.
 */
export function extractQuestions(data: unknown): Question[] | null {
  if (typeof data !== "object" || data === null || !("questions" in data)) {
    return null;
  }
  const questions = (data as { questions: unknown }).questions;
  if (!Array.isArray(questions) || questions.length === 0) return null;
  return questions.every(isQuestionLike) ? (questions as Question[]) : null;
}

/** Writable metadata from a full export; audit fields and scope are ignored. */
const importMetadataSchema = z.object({
  title: z.string().min(1),
  // Slug constraints belong to the editable confirmation form, so even an
  // older invalid slug can be corrected before any create request is sent.
  slug: z.string(),
  description: z.string().nullish(),
  subject_type: z.enum(SUBJECT_TYPES),
  version: z.union([z.string(), z.number()]).optional(),
  code: z.object({ system: z.string(), code: z.string(), display: z.string() }).optional(),
  actions: z.array(z.object({
    condition: z.string(),
    instructions: z.array(z.object({
      slug: z.string(),
      params: z.record(z.string(), z.unknown()),
      context: z.string().default("self"),
    })).default([]),
  })).nullish(),
});

export function parseQuestionnaireImport(data: unknown) {
  const metadata = importMetadataSchema.safeParse(data);
  const questions = extractQuestions(data);
  if (!metadata.success || !questions) return null;
  return { ...metadata.data, questions };
}

export type ImportedQuestionnaire = NonNullable<ReturnType<typeof parseQuestionnaireImport>>;
import { zodResolver } from "@hookform/resolvers/zod";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { navigate } from "raviger";
import { useMemo, useState } from "react";
import { useForm } from "react-hook-form";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

import { questionnaireKeys } from "@/components/QuestionnaireV2/queryKeys";
import { remapActionLinkIds } from "@/components/QuestionnaireV2/shared/actionExpression";
import {
  ImportedQuestionnaire,
  parseQuestionnaireImport,
} from "@/components/QuestionnaireV2/shared/questionnaireImport";
import { regenerateQuestionIdsWithMap } from "@/components/QuestionnaireV2/shared/questionTree";

import {
  QuestionnaireScope,
  SUBJECT_TYPES_FOR_CONTEXT,
  scopeCreateFields,
} from "@/types/questionnaire/questionnaire";
import questionnaireApi from "@/types/questionnaire/questionnaireApi";
import mutate from "@/Utils/request/mutate";

import { questionnaireBasicSchema } from "./questionnaireFormSchema";

interface ImportQuestionnaireDialogProps {
  scope: QuestionnaireScope;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

interface ImportIdentityValues {
  title: string;
  slug: string;
}

/** Imports a complete definition as a new draft in the current scope. */
export function ImportQuestionnaireDialog({
  scope,
  open,
  onOpenChange,
}: ImportQuestionnaireDialogProps) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const [pending, setPending] = useState<ImportedQuestionnaire | null>(null);
  const [fileError, setFileError] = useState<string>();
  const schema = useMemo(
    () => questionnaireBasicSchema(t).pick({ title: true, slug: true }),
    [t],
  );
  const form = useForm<ImportIdentityValues>({
    resolver: zodResolver(schema),
    defaultValues: { title: "", slug: "" },
  });

  const { mutate: create, isPending } = useMutation({
    mutationFn: mutate(questionnaireApi.createV2),
    onSuccess: (created) => {
      queryClient.invalidateQueries({ queryKey: questionnaireKeys.all });
      toast.success(t("questionnaire_imported_successfully"));
      onOpenChange(false);
      navigate(`${scope.basePath}/${created.id}`);
    },
  });

  const readFile = async (file: File) => {
    setFileError(undefined);
    try {
      if (file.size > 5_000_000) {
        setFileError(t("file_too_large"));
        return;
      }
      const imported = parseQuestionnaireImport(JSON.parse(await file.text()));
      if (!imported) {
        setFileError(t("invalid_json"));
        return;
      }
      if (!SUBJECT_TYPES_FOR_CONTEXT[scope.authContext].includes(imported.subject_type)) {
        setFileError(t("import_questionnaire_subject_unavailable", { subject: t(imported.subject_type) }));
        return;
      }
      setPending(imported);
      form.reset({ title: imported.title, slug: imported.slug });
    } catch {
      setFileError(t("invalid_json"));
    }
  };

  const onSubmit = (values: ImportIdentityValues) => {
    if (!pending) return;
    const { questions, linkIdMap } = regenerateQuestionIdsWithMap(pending.questions);
    create({
      ...values,
      description: pending.description ?? "",
      version: pending.version == null ? "1.0" : String(pending.version),
      code: pending.code,
      status: "draft",
      subject_type: pending.subject_type,
      questions,
      actions: remapActionLinkIds(pending.actions ?? [], linkIdMap),
      ...scopeCreateFields(scope),
    });
  };

  return (
    <Dialog open={open} onOpenChange={(next) => { if (!isPending) onOpenChange(next); }}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>{t("import_questionnaire")}</DialogTitle>
          <DialogDescription>{t("import_questionnaire_draft_description")}</DialogDescription>
        </DialogHeader>
        {pending ? (
          <Form {...form}>
            <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
              <FormField control={form.control} name="title" render={({ field }) => (
                <FormItem>
                  <FormLabel aria-required>{t("title")}</FormLabel>
                  <FormControl><Input {...field} disabled={isPending} /></FormControl>
                  <FormMessage />
                </FormItem>
              )} />
              <FormField control={form.control} name="slug" render={({ field }) => (
                <FormItem>
                  <FormLabel aria-required>{t("slug")}</FormLabel>
                  <FormControl><Input {...field} disabled={isPending} /></FormControl>
                  <FormDescription>{t("slug_format_message")}</FormDescription>
                  <FormMessage />
                </FormItem>
              )} />
              <div className="flex flex-wrap items-center gap-2 text-sm">
                <span>{t("subject_type")}: {t(pending.subject_type)}</span>
                <Badge variant="yellow">{t("draft")}</Badge>
              </div>
              <p className="text-sm text-gray-500">{t("questions_count")}: {pending.questions.length}</p>
              <DialogFooter>
                <Button type="button" variant="outline" disabled={isPending} onClick={() => setPending(null)}>{t("back")}</Button>
                <Button type="submit" disabled={isPending}>{isPending ? t("importing") : t("import")}</Button>
              </DialogFooter>
            </form>
          </Form>
        ) : (
          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="questionnaire-import-file">{t("json_files_only")}</Label>
              <Input id="questionnaire-import-file" type="file" accept="application/json,.json" onChange={(event) => {
                const file = event.target.files?.[0];
                if (file) void readFile(file);
                event.target.value = "";
              }} />
              {fileError && <p role="alert" className="text-sm text-destructive">{fileError}</p>}
            </div>
            <DialogFooter><Button type="button" variant="outline" onClick={() => onOpenChange(false)}>{t("cancel")}</Button></DialogFooter>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

