          >
            {t("editing")}
          </span>
          <div className="absolute -top-4 right-3 z-10 flex items-center gap-0.5 rounded-lg border border-gray-200 bg-white p-0.5 shadow-md">
            {toolbarButton(
              t("move_question_up"),
              ArrowUp,
              () =>
                studio.dispatch({
                  type: "moveQuestion",
                  id: question.id,
                  direction: "up",
                }),
              { disabled: index === 0 },
            )}
            {toolbarButton(
              t("move_question_down"),
              ArrowDown,
              () =>
