import { FullConfig } from "@playwright/test";
import { execFileSync } from "child_process";
import * as fs from "fs";
import * as path from "path";

// Token name constants
const ACCESS_TOKEN_KEY = "care_access_token";
const REFRESH_TOKEN_KEY = "care_refresh_token";

/**
 * Interface for localStorage items in Playwright storage state
 */
interface LocalStorageItem {
  name: string;
  value: string;
}

/**
 * Restore database from snapshot before tests run.
 * Ensures a clean, repeatable state for every test execution.
 * Skipped on CI (CI uses fresh Docker containers per run).
 */
function restoreDatabase() {
  if (process.env.CI) return;

  const snapshotFile =
    process.env.PLAYWRIGHT_DB_SNAPSHOT || "/tmp/care_playwright_snapshot.dump";
  const scriptPath = path.resolve(__dirname, "../scripts/playwright-db.sh");

  if (!fs.existsSync(snapshotFile)) {
    console.log(
      "⚠️ No DB snapshot found. Run 'npm run playwright:db-reset' to create one.",
    );
    return;
  }

  if (!fs.existsSync(scriptPath)) {
    console.log("⚠️ playwright-db.sh not found, skipping DB restore");
    return;
  }

  try {
    console.log("🔄 Restoring database from snapshot...");
    const output = execFileSync("bash", [scriptPath, "restore"], {
      stdio: "pipe",
      timeout: 30000,
      encoding: "utf-8",
    });
    if (output) console.log(output.trim());
    console.log("✅ Database restored to clean state");
  } catch (error) {
    const stderr =
      error instanceof Error && "stderr" in error
        ? (error as { stderr: string }).stderr
        : "";
    console.error(
      "⚠️ DB restore failed (tests will continue):",
      stderr || (error instanceof Error ? error.message : error),
    );
  }
}

/**
 * Refresh authentication tokens for every saved storage state using native
 * fetch. All role states (user/nurse/facilityAdmin) must be refreshed —
 * runs with `--no-deps` skip the setup project, and a stale nurse token
 * fails every permission spec while the admin ones keep passing.
 */
async function refreshTokens() {
  const authDir = path.join(__dirname, ".auth");
  if (!fs.existsSync(authDir)) {
    console.log("⚠️ Auth directory not found, skipping token refresh");
    return;
  }
  for (const file of fs.readdirSync(authDir)) {
    if (!file.endsWith(".json")) continue;
    await refreshTokensInFile(path.join(authDir, file));
  }
}

async function refreshTokensInFile(authFile: string) {
  if (!fs.existsSync(authFile)) {
    console.log("⚠️ Auth file not found, skipping token refresh");
    return;
  }

  try {
    const storageState = JSON.parse(fs.readFileSync(authFile, "utf-8"));

    if (
      !Array.isArray(storageState.origins) ||
      storageState.origins.length === 0
    ) {
      // Not a storage state (e.g. a *Meta.json id file) — nothing to refresh.
      return;
    }

    const firstOrigin = storageState.origins[0];
    const localStorage: LocalStorageItem[] = Array.isArray(
      firstOrigin.localStorage,
    )
      ? firstOrigin.localStorage
      : [];
    const accessTokenEntry = localStorage.find(
      (item: LocalStorageItem) => item.name === ACCESS_TOKEN_KEY,
    );
    const refreshTokenEntry = localStorage.find(
      (item: LocalStorageItem) => item.name === REFRESH_TOKEN_KEY,
    );

    if (!accessTokenEntry || !refreshTokenEntry) {
      console.log(`⚠️ No tokens found in ${path.basename(authFile)}`);
      return;
    }

    const refreshToken = refreshTokenEntry.value;
    const apiUrl = process.env.REACT_CARE_API_URL || "http://localhost:9000";

    console.log(`🔄 Refreshing tokens (${path.basename(authFile)})...`);

    const response = await fetch(`${apiUrl}/api/v1/auth/token/refresh/`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ refresh: refreshToken }),
    });

    if (response.ok) {
      const data = await response.json();

      const accessIndex = localStorage.findIndex(
        (item: LocalStorageItem) => item.name === ACCESS_TOKEN_KEY,
      );
      const refreshIndex = localStorage.findIndex(
        (item: LocalStorageItem) => item.name === REFRESH_TOKEN_KEY,
      );

      if (accessIndex !== -1) {
        localStorage[accessIndex].value = data.access;
      }
      if (refreshIndex !== -1 && data.refresh) {
        localStorage[refreshIndex].value = data.refresh;
      }

      fs.writeFileSync(authFile, JSON.stringify(storageState, null, 2));

      console.log(`✅ Tokens refreshed (${path.basename(authFile)})`);
    } else {
      console.log(
        `⚠️ Token refresh failed for ${path.basename(authFile)} with status: ${response.status}`,
      );
    }
  } catch (error) {
    console.error("❌ Error refreshing tokens:", error);
  }
}

/**
 * Global setup that runs once before all tests.
 * 1. Restores database from snapshot (local only)
 * 2. Refreshes authentication tokens
 */
async function globalSetup(_config: FullConfig) {
  restoreDatabase();
  await refreshTokens();
}

export default globalSetup;
import { expect, type Page } from "@playwright/test";
import * as fs from "fs";
import * as path from "path";

import { expectToast } from "./ui";

/** Deterministic backend fixtures loaded by the care repo's E2E fixture
 *  script (present in the Playwright DB snapshot, so restores keep them). */
export const KITCHEN_SINK_FACILITY_SLUG = "e2e-kitchen-sink-facility";
export const KITCHEN_SINK_INSTANCE_SLUG = "e2e-kitchen-sink-instance";
export const VERSIONED_SLUG = "e2e-versioned";
/** 18 records named `E2E Pagination 001..018`, facility-scoped, active. */
export const PAGINATION_TITLE_PREFIX = "E2E Pagination";
export const PAGINATION_FIXTURE_COUNT = 18;

/** Reads the admin bearer token captured by tests/setup/auth.setup.ts. */
export function adminApiHeaders(): Record<string, string> {
  const authFile = path.resolve("tests/.auth/user.json");
  const storageState = JSON.parse(fs.readFileSync(authFile, "utf-8"));
  const localStorage: { name: string; value: string }[] =
    storageState.origins?.[0]?.localStorage ?? [];
  const token = localStorage.find(
    (item) => item.name === "care_access_token",
  )?.value;
  if (!token) {
    throw new Error("No access token in tests/.auth/user.json — run setup");
  }
  return {
    Authorization: `Bearer ${token}`,
    "Content-Type": "application/json",
  };
}

export function apiBaseUrl(): string {
  return process.env.REACT_CARE_API_URL || "http://localhost:9000";
}

const slugCache = new Map<string, string>();

/**
 * Resolves a fixture questionnaire's id from its slug. The detail endpoint
 * looks up by external_id only (slug lookup is not supported) and the list
 * has no slug filter, so this lists broadly and matches client-side.
 */
export async function getQuestionnaireIdBySlug(slug: string): Promise<string> {
  const cached = slugCache.get(slug);
  if (cached) return cached;

  const limit = 100;
  let offset = 0;

  while (true) {
    const res = await fetch(
      `${apiBaseUrl()}/api/v1/questionnaire/?limit=${limit}&offset=${offset}`,
      {
        headers: adminApiHeaders(),
      },
    );
    if (!res.ok) {
      throw new Error(`Failed to list questionnaires: ${res.status}`);
    }
    const data = (await res.json()) as {
      results: { id: string; slug: string }[];
    };

    // Cache and check all results on this page
    for (const entry of data.results) {
      slugCache.set(entry.slug, entry.id);
      if (entry.slug === slug) {
        return entry.id;
      }
    }

    // If we got fewer results than the limit, we've reached the end
    if (data.results.length < limit) {
      break;
    }

    offset += limit;
  }

  throw new Error(
    `Fixture questionnaire "${slug}" not found — reload backend E2E fixtures`,
  );
}

/** Matches the questionnaire v2 detail URL on both mounts
 *  (`/facility/{id}/settings/questionnaires/{uuid}` and
 *  `/admin/questionnaires/{uuid}`). */
export const QUESTIONNAIRE_DETAIL_URL = /\/questionnaires\/[0-9a-f-]+$/;

export interface CreateQuestionnaireOptions {
  /** Mount base path, e.g. `/facility/${facilityId}/settings/questionnaires`
   *  or `/admin/questionnaires`. */
  basePath: string;
  /** Generate unique titles per PLAYWRIGHT_GUIDE (faker/Date.now). */
  title: string;
  /** Status radio to pick before saving (display label); default Draft. */
  status?: "Active" | "Draft" | "Retired";
}

/**
 * Drives the v2 create form end-to-end: open `${basePath}/new`, type the
 * title, submit, wait for the created toast and the detail-page redirect.
 * Returns the detail page URL.
 */
export async function createQuestionnaire(
  page: Page,
  { basePath, title, status }: CreateQuestionnaireOptions,
): Promise<string> {
  await page.goto(`${basePath}/new`);
  await page.getByRole("textbox", { name: "Title" }).pressSequentially(title);
  if (status) {
    await page
      .getByRole("radiogroup", { name: "Status" })
      .getByRole("radio", { name: status })
      .click();
  }
  await page.getByRole("button", { name: "Save Questionnaire" }).click();
  await expectToast(page, "Questionnaire created successfully");
  await page.waitForURL(QUESTIONNAIRE_DETAIL_URL);
  return page.url();
}

/** From the detail page, opens the question builder (`…/{id}/edit`). */
export async function openQuestionBuilder(page: Page): Promise<void> {
  await page.getByRole("button", { name: "Edit Questions" }).click();
  await page.waitForURL(/\/edit$/);
}

/** createQuestionnaire + openQuestionBuilder; returns the detail page URL. */
export async function createQuestionnaireAndOpenBuilder(
  page: Page,
  options: CreateQuestionnaireOptions,
): Promise<string> {
  const detailUrl = await createQuestionnaire(page, options);
  await openQuestionBuilder(page);
