                text: outerTitle,
                type: "group",
                link_id: "outer",
                questions: [
                  {
                    text: innerTitle,
                    type: "group",
                    link_id: "inner",
                    styling_metadata: { containerClasses: "grid grid-cols-1" },
                    questions: [
                      {
                        text: leafTitles[0],
                        type: "string",
                        link_id: "nested_leaf",
                      },
                      {
                        text: deepTitle,
                        type: "group",
                        link_id: "deep",
                        styling_metadata: {
                          containerClasses: "grid grid-cols-1",
                        },
                        questions: [
                          {
                            text: leafTitles[1],
                            type: "string",
                            link_id: "deep_leaf",
                          },
                        ],
                      },
                    ],
                  },
                ],
              },
            ],
          }),
        ),
      });
