      for (const name of ["Patients", "Billing", "RBAC", "Organizations"]) {
        localStorage.removeItem(`nav-expansion-state--${name}`);
      }
    });

    const updateNotice = page.locator("li[data-sonner-toast]").filter({
      hasText: "Software Update",
    });
