  const context = useContext(FormContext);
  if (!context) {
    throw new Error(
      "useFormRenderer must be used inside QuestionnaireFormProvider",
    );
  }
  return context;
}

/**
 * `id → signature` for every non-group question — the key that decides
 * whether an in-progress answer survives a live tree update. Participates:
 * type/structured_type (a differently-shaped value must not linger),
 * answer options (value + default flag — a changed `initial_selected` must
 * reach the preview, and a recorded answer can't point at a removed
 * option), `repeats` (turning it off collapses rendering to `values[0]`
 * while enable_when and required validation still scan every entry — extra
 * entries would be invisible but live), and the answer value set (swapping
 * sets would leave the old set's `coding` recorded).
 */
function questionSignatures(questions: Question[]): Map<string, string> {
  const signatures = new Map<string, string>();
  const walk = (list: Question[]) => {
    for (const question of list) {
      if (question.type === "group") {
        walk(question.questions ?? []);
        continue;
      }
      const options = (question.answer_option ?? [])
        .map((option) => `${option.value}=${option.initial_selected ? 1 : 0}`)
        .join("|");
      const valueSet = question.answer_value_set
        ? `${question.answer_value_set.slug ?? ""}/${question.answer_value_set.external_id ?? ""}`
        : "";
      signatures.set(
        question.id,
        `${question.type}:${question.structured_type ?? ""}:${question.repeats ? 1 : 0}:${valueSet}:${options}`,
      );
    }
  };
  walk(questions);
  return signatures;
}

/**
 * Live-update merge — the difference from the old renderer's wholesale
 * re-seed (which wiped every in-progress answer whenever the questionnaire
 * identity changed). Entries survive when the question id still exists with
 * the same type/structured_type; added questions get fresh seeded entries
 * (`initial_selected` options); removed questions drop; a type change
 * re-seeds that one entry so a stale value of another shape can't linger in
 * enable_when evaluation.
 */
function syncResponses(
  previous: Record<string, QuestionnaireResponse>,
  previousSignatures: Map<string, string>,
  questions: Question[],
): Record<string, QuestionnaireResponse> {
  const fresh = initializeResponses(questions);
  const nextSignatures = questionSignatures(questions);
  const merged: Record<string, QuestionnaireResponse> = {};
  for (const [id, seeded] of Object.entries(fresh)) {
    const existing = previous[id];
    if (!existing || previousSignatures.get(id) !== nextSignatures.get(id)) {
      merged[id] = seeded;
      continue;
    }
    // Preserve object identity when nothing about the entry changed, so
    // each useQuestionResponse derived atom keeps its Jotai bail-out —
    // a title keystroke in the builder must not re-render every block.
    merged[id] =
      existing.link_id === seeded.link_id
        ? existing
        : { ...existing, link_id: seeded.link_id };
  }
  return merged;
}

interface ProviderProps {
  questionnaire: QuestionnaireRead;
  mode: FormMode;
  subject?: RendererSubject;
  revealHidden?: boolean;
  inert?: boolean;
  /** See `FormContextValue.frozen`. Defaults false — only the fill host's
   *  submit window ever sets it. */
  frozen?: boolean;
  /**
   * Creation-time seed overrides (a restored fill draft). Applied once,
   * merged over `initializeResponses` so the store is never observed
   * unseeded; entries only take effect when the question id still exists
   * with the same structured_type (both restore paths already run the
   * draft through `mergeDraftResponses`, which drops per QUESTION and
   * names what it dropped — this is defense in depth). Changing the prop
   * after mount has no effect by design.
   */
  initialResponses?: Record<string, QuestionnaireResponse>;
  children: React.ReactNode;
}

export function QuestionnaireFormProvider({
  questionnaire,
  mode,
  subject = EMPTY_SUBJECT,
  revealHidden = false,
  inert = false,
  frozen = false,
  initialResponses,
  children,
}: ProviderProps) {
  // useState (not useMemo) so the store is created exactly once per instance
  // and never observed unseeded (same rationale as the old provider).
  const [store] = useState(() => {
    const seeded = createStore();
    const responses = initializeResponses(questionnaire.questions);
    if (initialResponses) {
      for (const [id, entry] of Object.entries(initialResponses)) {
        const base = responses[id];
        if (base && base.structured_type === entry.structured_type) {
          responses[id] = { ...entry, question_id: id, link_id: base.link_id };
        }
      }
    }
    seeded.set(questionnaireAtom, questionnaire);
    seeded.set(responsesAtom, responses);
    return seeded;
  });

  // Live sync: every questionnaire identity change re-points the atom and
  // merges responses instead of wiping them — this is what lets the builder
  // feed a fresh draft object per keystroke while preview answers persist.
  const previousRef = useRef(questionnaire);
  useEffect(() => {
    if (previousRef.current === questionnaire) return;
    // Metadata-only drafts (Form-settings title/description ride along in
    // the studio draft) leave the question tree referentially identical —
    // re-point the questionnaire atom, skip the response merge entirely.
    if (previousRef.current.questions === questionnaire.questions) {
      previousRef.current = questionnaire;
      store.set(questionnaireAtom, questionnaire);
      return;
    }
    const previousSignatures = questionSignatures(
      previousRef.current.questions,
    );
    previousRef.current = questionnaire;
    store.set(questionnaireAtom, questionnaire);
    store.set(
      responsesAtom,
      syncResponses(
        store.get(responsesAtom),
        previousSignatures,
        questionnaire.questions,
      ),
    );
  }, [questionnaire, store]);

  // Every canvas component consumes this context, so a fresh object literal
  // per render would re-render every block on any host re-render (a studio
  // keystroke, a fill-page state change) — defeating the response-identity
  // preservation `syncResponses` above exists for.
  const actionRequiredLinkIds = useMemo(
    () =>
      new Set((questionnaire.actions ?? []).flatMap(actionReferencedLinkIds)),
    [questionnaire.actions],
  );
  const value = useMemo(
    () => ({
      mode,
      subject,
      questionnaire,
/**
 * Save-time rules for questionnaire actions — the counterpart of
 * `saveValidation.ts` for the question tree. Each rule names the first
 * action it fails on; the studio blocks Save until the list is empty.
 *
 * The backend only rejects an unknown instruction slug and missing
 * `condition`/`context` fields at save time; a bad expression, a missing
 * required param or a reference to a deleted or conditionally-shown
 * question would otherwise sail through the PUT and break every
 * SUBMISSION of the questionnaire instead.
 */
import {
  ActionInstructionDefinition,
  QuestionnaireAction,
} from "@/types/questionnaire/actions";
import { Question } from "@/types/questionnaire/question";
import type { ContextPathOption } from "./actionVariables";
import { isInstructionCompatible } from "./actions/instructionCompatibility";

import {
  actionReferencedLinkIds,
  lintExpression,
  parseTemplate,
} from "@/components/QuestionnaireV2/shared/actionExpression";

export interface ActionIssue {
  /** Index into the questionnaire's `actions` array. */
  index: number;
  messageKey: string;
}

export interface ActionCheckContext {
  questions: Question[];
  /** Undefined until the registry has loaded — the slug rules stand down
   *  rather than flag every action as unknown while the request is in
   *  flight. */
  instructions?: ActionInstructionDefinition[];
  /** Omitted while the field registry is loading or unavailable. */
  contextPaths?: ContextPathOption[];
}

interface TreeIndex {
  linkIds: Set<string>;
  /** link_ids of questions that are shown conditionally — themselves or
   *  through an enclosing group — and so can be absent from a submission
   *  however required they are. */
  conditional: Set<string>;
}

function indexTree(questions: Question[]): TreeIndex {
  const index: TreeIndex = { linkIds: new Set(), conditional: new Set() };
  const walk = (list: Question[], underCondition: boolean) => {
    for (const question of list) {
      const conditional =
        underCondition || (question.enable_when?.length ?? 0) > 0;
      index.linkIds.add(question.link_id);
      if (conditional) index.conditional.add(question.link_id);
      walk(question.questions ?? [], conditional);
    }
  };
  walk(questions, false);
  return index;
}

function isBlank(value: unknown): boolean {
  if (value === undefined || value === null) return true;
  if (typeof value !== "string") return false;
  if (value.trim() === "") return true;
  const template = parseTemplate(value);
  return template?.kind === "expression" && template.expression === "";
}

/** Every expression an action evaluates: its condition and each templated
 *  param's inner expression. */
function expressionsOf(action: QuestionnaireAction): string[] {
  const expressions = [action.condition];
  for (const instruction of action.instructions) {
    for (const value of Object.values(instruction.params)) {
      const template = parseTemplate(value);
      if (template) {
        expressions.push(
          template.kind === "ref" ? template.ref : template.expression,
        );
      }
    }
  }
  return expressions;
}

interface ActionRule {
  predicate: (
    action: QuestionnaireAction,
    tree: TreeIndex,
    instructions: ActionInstructionDefinition[] | undefined,
    contextPaths: ContextPathOption[] | undefined,
  ) => boolean;
  messageKey: string;
}

const ACTION_RULES: ActionRule[] = [
  {
    predicate: (action) => action.condition.trim() === "",
    messageKey: "action_issue_condition_empty",
  },
  {
    predicate: (action) =>
      expressionsOf(action).some(
        (expression) => lintExpression(expression) === "attribute",
      ),
    messageKey: "action_issue_expression_attribute",
  },
  {
    predicate: (action) =>
      expressionsOf(action).some(
        (expression) =>
          expression.trim() !== "" && lintExpression(expression) === "syntax",
      ),
    messageKey: "action_issue_expression_syntax",
  },
  {
    predicate: (action) => action.instructions.length === 0,
    messageKey: "action_issue_no_instructions",
  },
  {
    predicate: (action) =>
      action.instructions.some((instruction) => !instruction.slug),
    messageKey: "action_issue_instruction_missing",
  },
  {
    predicate: (action, _tree, instructions) =>
      !!instructions &&
      action.instructions.some(
        (instruction) =>
          instruction.slug &&
          !instructions.some(
            (definition) => definition.slug === instruction.slug,
          ),
      ),
    messageKey: "action_issue_instruction_unknown",
  },
  {
    predicate: (action, _tree, instructions, contextPaths) =>
      !!instructions &&
      !!contextPaths &&
      action.instructions.some((instruction) => {
        const definition = instructions.find(
          (candidate) => candidate.slug === instruction.slug,
        );
        return (
          !!definition && !isInstructionCompatible(definition, contextPaths)
        );
      }),
    messageKey: "action_instruction_incompatible",
  },
  {
    predicate: (action) =>
      action.instructions.some((instruction) => !instruction.context),
    messageKey: "action_issue_context_missing",
  },
  {
    predicate: (action, _tree, instructions) =>
      !!instructions &&
      action.instructions.some((instruction) => {
        const definition = instructions.find(
          (candidate) => candidate.slug === instruction.slug,
        );
        return (definition?.input_schema.required ?? []).some((name) =>
          isBlank(instruction.params[name]),
        );
      }),
    messageKey: "action_issue_param_required",
  },
  {
    predicate: (action, { linkIds }) =>
      actionReferencedLinkIds(action).some((linkId) => !linkIds.has(linkId)),
    messageKey: "action_issue_unknown_question",
  },
  {
    predicate: (action, { conditional }) =>
      actionReferencedLinkIds(action).some((linkId) => conditional.has(linkId)),
    messageKey: "action_issue_conditional_question",
  },
];

/** The first failing rule per action, in action order. */
export function findActionIssues(
  actions: QuestionnaireAction[],
  { questions, instructions, contextPaths }: ActionCheckContext,
): ActionIssue[] {
  const tree = indexTree(questions);
  const issues: ActionIssue[] = [];
  actions.forEach((action, index) => {
    const failing = ACTION_RULES.find((rule) =>
      rule.predicate(action, tree, instructions, contextPaths),
    );
    if (failing) issues.push({ index, messageKey: failing.messageKey });
  });
  return issues;
}

